"""Tests for backend/scripts/check_locks.py, the lock-drift guard (MS7 Task 14, D-l)."""

from __future__ import annotations

import subprocess
import sys
from pathlib import Path

import check_locks
import pytest

EXPORT_BODY = (
    "anyio==4.15.1 \\\n"
    "    --hash=sha256:" + "a" * 64 + "\n"
    "httpx==0.28.1 \\\n"
    "    --hash=sha256:" + "b" * 64 + "\n"
)
COMMITTED_HEADER = (
    "# This file was autogenerated by uv via the following command:\n"
    "#    uv export --no-dev --no-emit-project --format requirements-txt -o requirements.lock.txt\n"
)
EXPORT_HEADER = (
    "# This file was autogenerated by uv via the following command:\n"
    "#    uv export --frozen --no-dev --no-emit-project --format requirements-txt\n"
)


@pytest.fixture
def repo(tmp_path):
    """A repo with the analysis package's locks, two locked scripts, one without a lock, and
    MS6's eval runner."""
    analysis = tmp_path / "backend" / "analysis"
    analysis.mkdir(parents=True)
    (analysis / "uv.lock").write_text("version = 1\n", encoding="utf-8")
    (analysis / "requirements.lock.txt").write_text(
        COMMITTED_HEADER + EXPORT_BODY, encoding="utf-8"
    )
    scripts = tmp_path / "backend" / "scripts"
    scripts.mkdir(parents=True)
    for name in ("alpha.py", "beta.py", "helper.py"):
        (scripts / name).write_text("print('x')\n", encoding="utf-8")
    for name in ("alpha.py.lock", "beta.py.lock"):
        (scripts / name).write_text("version = 1\n", encoding="utf-8")
    tests = tmp_path / "eval" / "tests"
    tests.mkdir(parents=True)
    (tests / "run_tests.py").write_text("print('x')\n", encoding="utf-8")
    (tests / "run_tests.py.lock").write_text("version = 1\n", encoding="utf-8")
    return tmp_path


class FakeUv:
    """Answers each uv command; `fail` holds the commands (as joined strings) that exit 1."""

    def __init__(
        self,
        export: str = EXPORT_HEADER + EXPORT_BODY,
        fail: frozenset[str] = frozenset(),
    ):
        self.export = export
        self.fail = fail
        self.calls: list[tuple[list[str], Path]] = []

    def __call__(self, args: list[str], cwd: Path) -> tuple[int, str]:
        self.calls.append((args, cwd))
        joined = " ".join(args)
        if joined in self.fail:
            return 1, ""
        if args[:2] == ["uv", "export"]:
            return 0, self.export
        return 0, ""


def test_clean_locks(repo):
    uv = FakeUv()
    assert check_locks.check(uv, repo) == []
    commands = [" ".join(args) for args, _ in uv.calls]
    assert "uv lock --check" in commands
    assert "uv lock --script backend/scripts/alpha.py --check" in commands
    assert "uv lock --script backend/scripts/beta.py --check" in commands
    assert "uv lock --script eval/tests/run_tests.py --check" in commands
    assert not any("helper.py" in c for c in commands), (
        "a script without a lock was checked"
    )
    cwd = {" ".join(args): where for args, where in uv.calls}
    assert cwd["uv lock --check"] == repo / "backend" / "analysis"
    assert cwd["uv lock --script backend/scripts/alpha.py --check"] == repo


def test_ms2_data_tool_locks_are_checked(repo):
    # MS7 Task 14's gap, found on Nov 2 (docs/log/2026-11-02.md): MS2's locked scripts in
    # eval/data, its tests runner and eval/set_b drift unseen otherwise. A script
    # without a lock is still left out.
    for folder, name in (
        ("eval/data", "intake.py"),
        ("eval/data/tests", "run_tests.py"),
        ("eval/set_b", "generate.py"),
    ):
        where = repo / folder
        where.mkdir(parents=True, exist_ok=True)
        (where / name).write_text("print('x')\n", encoding="utf-8")
        (where / (name + ".lock")).write_text("version = 1\n", encoding="utf-8")
    (repo / "eval" / "data" / "places.py").write_text("x = 1\n", encoding="utf-8")
    uv = FakeUv(fail=frozenset({"uv lock --script eval/set_b/generate.py --check"}))
    assert check_locks.check(uv, repo) == ["eval/set_b/generate.py.lock"]
    commands = [" ".join(args) for args, _ in uv.calls]
    for script in (
        "eval/data/intake.py",
        "eval/data/tests/run_tests.py",
        "eval/set_b/generate.py",
    ):
        assert f"uv lock --script {script} --check" in commands
    assert not any("places.py" in c for c in commands)


def test_each_kind_of_drift_is_named(repo):
    changed = EXPORT_HEADER + EXPORT_BODY.replace("httpx==0.28.1", "httpx==0.28.2")
    uv = FakeUv(
        export=changed,
        fail=frozenset(
            {"uv lock --check", "uv lock --script backend/scripts/beta.py --check"}
        ),
    )
    assert check_locks.check(uv, repo) == [
        "backend/analysis/uv.lock",
        "backend/analysis/requirements.lock.txt",
        "backend/scripts/beta.py.lock",
    ]


class ExportFailsWithMatchingBody(FakeUv):
    """An export that exits 1 but still prints the committed body."""

    def __call__(self, args, cwd):
        code, out = super().__call__(args, cwd)
        return (1, out) if args[:2] == ["uv", "export"] else (code, out)


def test_a_failed_export_is_drift(repo):
    assert check_locks.check(ExportFailsWithMatchingBody(), repo) == [
        "backend/analysis/requirements.lock.txt"
    ]


def test_a_changed_hash_alone_is_drift(repo):
    rehashed = EXPORT_HEADER + EXPORT_BODY.replace("b" * 64, "c" * 64)
    assert check_locks.check(FakeUv(export=rehashed), repo) == [
        "backend/analysis/requirements.lock.txt"
    ]


def test_a_missing_requirements_lock_is_drift(repo):
    (repo / "backend" / "analysis" / "requirements.lock.txt").unlink()
    assert check_locks.check(FakeUv(), repo) == [
        "backend/analysis/requirements.lock.txt"
    ]


def test_export_runs_in_the_analysis_package(repo):
    uv = FakeUv()
    check_locks.check(uv, repo)
    (where,) = [cwd for args, cwd in uv.calls if args[:2] == ["uv", "export"]]
    assert where == repo / "backend" / "analysis"


def test_run_returns_the_exit_code_and_stdout(tmp_path):
    # One write to the byte buffer, so the lines' order can't hang on the text layer's buffering
    # (a pipe is block-buffered unless PYTHONUNBUFFERED is set) or on the runner's locale.
    script = "import sys; sys.stdout.buffer.write(b'out\\n\\xff\\n'); sys.exit(3)"
    code, out = check_locks.run([sys.executable, "-c", script], tmp_path)
    assert code == 3
    assert out.splitlines()[0] == "out"
    assert "\ufffd" in out  # undecodable bytes are replaced, never a crash


def test_eval_runner_is_checked_only_if_it_exists(repo):
    (repo / "eval" / "tests" / "run_tests.py").unlink()
    (repo / "eval" / "tests" / "run_tests.py.lock").unlink()
    uv = FakeUv()
    assert check_locks.check(uv, repo) == []
    assert not any("run_tests.py" in " ".join(args) for args, _ in uv.calls)


def test_export_header_is_ignored(repo):
    # The export's header names its own command, which differs from the committed file's, and
    # a Windows uv may end its lines with CRLF.
    other = "# This file was autogenerated by uv via some other command\n" + EXPORT_BODY
    assert check_locks.check(FakeUv(export=other.replace("\n", "\r\n")), repo) == []
    assert check_locks.check(FakeUv(export=EXPORT_BODY), repo) == []


def test_export_never_writes_the_file(repo):
    lock = repo / "backend" / "analysis" / "requirements.lock.txt"
    before = lock.read_bytes()
    uv = FakeUv()
    check_locks.check(uv, repo)
    (export,) = [args for args, _ in uv.calls if args[:2] == ["uv", "export"]]
    assert "--frozen" in export
    assert not any(
        a in {"-o", "--output-file"} or a.startswith("--output-file=") for a in export
    )
    assert lock.read_bytes() == before


def test_main_names_each_drift_and_exits_by_it(repo, monkeypatch, capsys):
    monkeypatch.setattr(check_locks, "REPO", repo)
    monkeypatch.setattr(check_locks, "run", FakeUv())
    assert check_locks.main() == 0
    assert capsys.readouterr().out.strip() == "locks: clean"
    monkeypatch.setattr(check_locks, "run", FakeUv(fail=frozenset({"uv lock --check"})))
    assert check_locks.main() == 1
    assert capsys.readouterr().out.splitlines() == [
        "lock drift: backend/analysis/uv.lock",
        "locks: 1 drifted",
    ]


def test_main_exits_2_without_uv(repo, monkeypatch, capsys):
    def missing(args, cwd):
        raise FileNotFoundError("uv")

    monkeypatch.setattr(check_locks, "REPO", repo)
    monkeypatch.setattr(check_locks, "run", missing)
    assert check_locks.main() == 2
    assert "uv" in capsys.readouterr().err


def test_every_tracked_script_lock_is_checked():
    # The gap above came from a hard-coded folder list: every *.py.lock git tracks must
    # belong to a script the guard checks, so a lock in a new folder can't drift unseen.
    repo = Path(__file__).resolve().parents[2]
    tracked = subprocess.run(
        ["git", "ls-files", "*.py.lock"], cwd=repo, capture_output=True, text=True, check=True
    ).stdout.split()
    checked = {
        (p.relative_to(repo).as_posix() + ".lock") for p in check_locks.locked_scripts(repo)
    }
    assert tracked
    assert set(tracked) <= checked, sorted(set(tracked) - checked)
